export interface DaemonPaths { readonly pidPath: string; readonly logPath: string }
export const HOME_DIR_NAME = "sangkar";
export interface AppConfig {
  // existing, unchanged: dataDir, repoRoot, cursorKey, budgets, telemetry
  readonly home: string;         // $SANGKAR_HOME, else ${XDG_CONFIG_HOME:-$HOME/.config}/sangkar
  readonly registryPath: string; // <home>/sangkar.json
